import * as THREE from 'three';
import { PARALLAX_GLSL } from './parallax.js';

// Textures and shaders for the level 2 hub.
//
// The hub model is generated by code and has no UV coordinates, so ordinary image
// textures cannot be wrapped onto it. Instead the surfaces use TRIPLANAR MAPPING: the
// fragment shader works out each pixel's world position and projects the texture along
// the x, y and z axes, blending the three by how much the surface faces each way. Any
// shape gets tiled detail with no UV work, and the tile size is in metres.
//
// Two procedurally drawn textures (no image files, so they are ours and tiny):
//   plate  - riveted metal panels with seams, scratches, brushing and grime
//   floor  - tread plate: big panels with a diamond-bar tread
// Each has an albedo map (colour) and a height map. The height map drives BUMP MAPPING in
// the shader (it perturbs the surface normal, so the lights catch the rivets and seams)
// and the roughness (seams and grime are rougher, scratches shinier).
//
// The glowing materials get a second shader: light that flows through the strips.

const SIZE = 512;

// small deterministic random numbers so the textures look the same every run
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Draws everything wrapped, so the texture tiles without a visible edge
function wrapped(ctx, draw) {
  for (const ox of [-SIZE, 0, SIZE]) {
    for (const oy of [-SIZE, 0, SIZE]) draw(ox, oy);
  }
}

const gray = (v, a = 1) => `rgba(${Math.round(v * 255)},${Math.round(v * 255)},${Math.round(v * 255)},${a})`;

function paintNoise(ctx, amount, rand) {
  const img = ctx.getImageData(0, 0, SIZE, SIZE);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rand() - 0.5) * 255 * amount;
    d[i] += n; d[i + 1] += n; d[i + 2] += n;
  }
  ctx.putImageData(img, 0, 0);
}

// mode 'albedo' paints colour, mode 'height' paints relief (mid grey = flat)
function paintPlate(ctx, mode, seed) {
  const rand = rng(seed);
  const albedo = mode === 'albedo';
  ctx.fillStyle = albedo ? gray(0.62) : gray(0.55);
  ctx.fillRect(0, 0, SIZE, SIZE);

  // Each of the 2x2 panels is a slightly different shade
  for (let py = 0; py < 2; py++) {
    for (let px = 0; px < 2; px++) {
      const v = albedo ? 0.56 + rand() * 0.14 : 0.5 + rand() * 0.1;
      ctx.fillStyle = gray(v);
      ctx.fillRect(px * 256 + 3, py * 256 + 3, 250, 250);
    }
  }

  // Seams between panels (a dark groove with a thin highlight beside it)
  for (const c of [0, 256]) {
    ctx.strokeStyle = albedo ? gray(0.2) : gray(0.12);
    ctx.lineWidth = 4;
    wrapped(ctx, (ox, oy) => {
      ctx.beginPath(); ctx.moveTo(c + ox, oy); ctx.lineTo(c + ox, SIZE + oy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ox, c + oy); ctx.lineTo(SIZE + ox, c + oy); ctx.stroke();
    });
    ctx.strokeStyle = albedo ? gray(0.85, 0.5) : gray(0.85, 0.7);
    ctx.lineWidth = 1.5;
    wrapped(ctx, (ox, oy) => {
      ctx.beginPath(); ctx.moveTo(c + 4 + ox, oy); ctx.lineTo(c + 4 + ox, SIZE + oy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ox, c + 4 + oy); ctx.lineTo(SIZE + ox, c + 4 + oy); ctx.stroke();
    });
  }

  // Rivets: round heads along every panel edge
  const rivet = (x, y) => {
    wrapped(ctx, (ox, oy) => {
      ctx.fillStyle = albedo ? gray(0.2) : gray(0.95);
      ctx.beginPath(); ctx.arc(x + ox, y + oy, 5.2, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = albedo ? gray(0.78) : gray(1);
      ctx.beginPath(); ctx.arc(x + ox - 1, y + oy - 1, 2.6, 0, Math.PI * 2); ctx.fill();
    });
  };
  for (const cx of [0, 256]) {
    for (const cy of [0, 256]) {
      for (const [dx, dy] of [[16, 16], [-16, 16], [16, -16], [-16, -16], [64, 16], [-64, 16], [64, -16], [-64, -16], [16, 64], [16, -64], [-16, 64], [-16, -64]]) {
        rivet(cx + dx, cy + dy);
      }
    }
  }

  // Hatch plates and vents on some panels
  for (let i = 0; i < 3; i++) {
    const x = 40 + rand() * 180 + (rand() > 0.5 ? 256 : 0);
    const y = 60 + rand() * 120 + (rand() > 0.5 ? 256 : 0);
    const w = 50 + rand() * 40, h = 20 + rand() * 24;
    wrapped(ctx, (ox, oy) => {
      ctx.fillStyle = albedo ? gray(0.34) : gray(0.35);
      ctx.fillRect(x + ox, y + oy, w, h);
      ctx.strokeStyle = albedo ? gray(0.08) : gray(0.15);
      ctx.lineWidth = 2;
      ctx.strokeRect(x + ox, y + oy, w, h);
      for (let s = 6; s < h - 3; s += 5) {
        ctx.strokeStyle = albedo ? gray(0.12) : gray(0.1);
        ctx.beginPath(); ctx.moveTo(x + ox + 4, y + oy + s); ctx.lineTo(x + ox + w - 4, y + oy + s); ctx.stroke();
      }
    });
  }

  // Scratches
  for (let i = 0; i < 16; i++) {
    const x = rand() * SIZE, y = rand() * SIZE, len = 30 + rand() * 90, ang = rand() * Math.PI;
    ctx.strokeStyle = albedo ? gray(0.85, 0.12) : gray(0.3, 0.3);
    ctx.lineWidth = 2;
    wrapped(ctx, (ox, oy) => { ctx.beginPath(); ctx.moveTo(x + ox, y + oy); ctx.lineTo(x + ox + Math.cos(ang) * len, y + oy + Math.sin(ang) * len); ctx.stroke(); });
  }

  // Grime: dark soft blotches, heavier near the seams
  for (let i = 0; i < 7; i++) {
    const x = rand() * SIZE, y = rand() * SIZE, r = 30 + rand() * 80;
    wrapped(ctx, (ox, oy) => {
      const g = ctx.createRadialGradient(x + ox, y + oy, 0, x + ox, y + oy, r);
      g.addColorStop(0, albedo ? 'rgba(20,24,30,0.12)' : 'rgba(30,30,30,0.12)');
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.fillRect(x + ox - r, y + oy - r, r * 2, r * 2);
    });
  }
}

function paintFloor(ctx, mode, seed) {
  const rand = rng(seed);
  const albedo = mode === 'albedo';
  ctx.fillStyle = albedo ? gray(0.5) : gray(0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);

  // A research-lab floor: large smooth tiles, each a slightly different shade, with fine
  // dark joints between them and the odd round service port
  const T = 128;
  for (let ty = 0; ty < SIZE / T; ty++) {
    for (let tx = 0; tx < SIZE / T; tx++) {
      // (the random number is drawn in both maps, so their hatches land on the same tiles)
      const shade = rand();
      const v = albedo ? 0.46 + shade * 0.08 : 0.5;
      ctx.fillStyle = gray(v);
      ctx.fillRect(tx * T + 2, ty * T + 2, T - 4, T - 4);
      if (rand() < 0.12) {
        const cx = tx * T + T / 2, cy = ty * T + T / 2;
        ctx.strokeStyle = albedo ? gray(0.22) : gray(0.08);
        ctx.lineWidth = 5;
        ctx.beginPath(); ctx.arc(cx, cy, T * 0.28, 0, Math.PI * 2); ctx.stroke();
        ctx.fillStyle = albedo ? gray(0.34) : gray(0.36);
        ctx.beginPath(); ctx.arc(cx, cy, T * 0.2, 0, Math.PI * 2); ctx.fill();
      }
    }
  }
  for (let c = 0; c <= SIZE; c += T) {
    ctx.strokeStyle = albedo ? gray(0.16) : gray(0.05);
    ctx.lineWidth = albedo ? 3 : 4;
    wrapped(ctx, (ox, oy) => {
      ctx.beginPath(); ctx.moveTo(c + ox, oy); ctx.lineTo(c + ox, SIZE + oy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ox, c + oy); ctx.lineTo(SIZE + ox, c + oy); ctx.stroke();
    });
  }

  // Very light scuffing, so it reads as used but clean
  for (let i = 0; i < 8; i++) {
    const x = rand() * SIZE, y = rand() * SIZE, r = 40 + rand() * 90;
    wrapped(ctx, (ox, oy) => {
      const g = ctx.createRadialGradient(x + ox, y + oy, 0, x + ox, y + oy, r);
      g.addColorStop(0, albedo ? 'rgba(20,24,30,0.1)' : 'rgba(40,40,40,0.08)');
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.fillRect(x + ox - r, y + oy - r, r * 2, r * 2);
    });
  }
}

// ---- Realistic surfaces for furniture and objects (the lab). Albedo maps sit around 0.69 grey,
// because the shader brightens them by 1.45: plain areas then keep the material's own colour.

function softBlobs(ctx, rand, n, rMin, rMax, colour) {
  for (let i = 0; i < n; i++) {
    const x = rand() * SIZE, y = rand() * SIZE, r = rMin + rand() * (rMax - rMin);
    wrapped(ctx, (ox, oy) => {
      const g = ctx.createRadialGradient(x + ox, y + oy, 0, x + ox, y + oy, r);
      g.addColorStop(0, colour);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.fillRect(x + ox - r, y + oy - r, r * 2, r * 2);
    });
  }
}

function fineScratches(ctx, rand, n, colour, maxLen = 60) {
  ctx.strokeStyle = colour;
  ctx.lineWidth = 1;
  for (let i = 0; i < n; i++) {
    const x = rand() * SIZE, y = rand() * SIZE, len = 8 + rand() * maxLen, a = rand() * Math.PI;
    wrapped(ctx, (ox, oy) => { ctx.beginPath(); ctx.moveTo(x + ox, y + oy); ctx.lineTo(x + ox + Math.cos(a) * len, y + oy + Math.sin(a) * len); ctx.stroke(); });
  }
}

// powder-coated metal furniture: a fine orange-peel grain, faint wear and hairline scratches
function paintPaint(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.69 : 0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);
  paintNoise(ctx, albedo ? 0.05 : 0.22, rand);
  if (albedo) {
    softBlobs(ctx, rand, 6, 30, 90, 'rgba(255,255,255,0.05)');
    softBlobs(ctx, rand, 5, 20, 70, 'rgba(0,0,0,0.05)');
  }
  fineScratches(ctx, rand, 24, albedo ? 'rgba(255,255,255,0.12)' : 'rgba(40,40,40,0.5)');
}

// moulded plastic: almost smooth, a few smudges and fingerprints
function paintPlastic(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.69 : 0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);
  paintNoise(ctx, albedo ? 0.02 : 0.08, rand);
  softBlobs(ctx, rand, 10, 10, 45, albedo ? 'rgba(0,0,0,0.06)' : 'rgba(255,255,255,0.08)');
  fineScratches(ctx, rand, 10, albedo ? 'rgba(0,0,0,0.06)' : 'rgba(60,60,60,0.35)', 30);
}

// woven fabric: threads going over and under each other
function paintFabric(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.6 : 0.35);
  ctx.fillRect(0, 0, SIZE, SIZE);
  const T = 16;
  for (let y = 0; y < SIZE; y += T) {
    for (let x = 0; x < SIZE; x += T) {
      const over = ((x + y) / T) % 2 === 0;
      const v = albedo ? 0.66 + rand() * 0.1 : 0.75;
      ctx.fillStyle = gray(v);
      if (over) ctx.fillRect(x + 1, y + 3, T - 2, T - 6);
      else ctx.fillRect(x + 3, y + 1, T - 6, T - 2);
    }
  }
  paintNoise(ctx, albedo ? 0.04 : 0.1, rand);
}

// printed paper: a header, rows of text, a small table and a chart
function paintPaper(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.69 : 0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);
  if (!albedo) return;
  const ink = (v) => gray(v * 0.69);
  ctx.fillStyle = ink(0.25);
  ctx.fillRect(40, 30, 220, 18);                                     // title
  ctx.fillRect(40, 56, 120, 8);
  for (let r = 0; r < 14; r++) {                                     // text lines made of words
    let x = 40;
    const y = 90 + r * 16;
    const end = r % 5 === 4 ? 260 : 470;
    while (x < end) {
      const w = 10 + rand() * 40;
      ctx.fillStyle = ink(0.35 + rand() * 0.1);
      ctx.fillRect(x, y, Math.min(w, end - x), 6);
      x += w + 6;
    }
  }
  ctx.strokeStyle = ink(0.35);                                       // a table
  ctx.lineWidth = 1.5;
  for (let r = 0; r <= 5; r++) { ctx.beginPath(); ctx.moveTo(40, 330 + r * 22); ctx.lineTo(280, 330 + r * 22); ctx.stroke(); }
  for (const c of [40, 120, 200, 280]) { ctx.beginPath(); ctx.moveTo(c, 330); ctx.lineTo(c, 440); ctx.stroke(); }
  ctx.beginPath();                                                    // a chart
  ctx.moveTo(310, 440); ctx.lineTo(310, 330); ctx.moveTo(310, 440); ctx.lineTo(470, 440); ctx.stroke();
  ctx.strokeStyle = 'rgba(40,70,150,0.8)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  for (let i = 0; i <= 10; i++) { const x = 315 + i * 15, y = 420 - rand() * 80; i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
  ctx.stroke();
}

// a printed bottle or box label: a dark band, text, hazard diamond and a barcode
function paintLabel(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.69 : 0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);
  if (!albedo) return;
  const ink = (v) => gray(v * 0.69);
  for (let k = 0; k < 2; k++) {
    const oy = k * 256;
    ctx.fillStyle = 'rgba(30,60,120,0.85)';
    ctx.fillRect(0, oy + 20, SIZE, 50);
    ctx.fillStyle = ink(0.95);
    ctx.fillRect(30, oy + 35, 160, 18);
    for (let r = 0; r < 5; r++) {
      ctx.fillStyle = ink(0.3);
      ctx.fillRect(30, oy + 90 + r * 18, 120 + rand() * 200, 7);
    }
    ctx.save();                                                        // hazard diamond
    ctx.translate(430, oy + 140); ctx.rotate(Math.PI / 4);
    ctx.strokeStyle = 'rgba(200,30,20,0.9)'; ctx.lineWidth = 6;
    ctx.strokeRect(-26, -26, 52, 52);
    ctx.restore();
    let x = 30;                                                        // barcode
    while (x < 230) {
      const w = 1 + Math.floor(rand() * 4);
      ctx.fillStyle = ink(0.1);
      ctx.fillRect(x, oy + 195, w, 40);
      x += w + 1 + Math.floor(rand() * 3);
    }
  }
}

// brushed steel: fine streaks all in one direction
function paintBrushed(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.69 : 0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);
  for (let i = 0; i < 900; i++) {
    const y = rand() * SIZE, x = rand() * SIZE, len = 60 + rand() * 260;
    ctx.strokeStyle = albedo ? gray(0.6 + rand() * 0.18, 0.5) : gray(0.42 + rand() * 0.16, 0.6);
    ctx.lineWidth = 1;
    wrapped(ctx, (ox, oy) => { ctx.beginPath(); ctx.moveTo(x + ox, y + oy); ctx.lineTo(x + ox + len, y + oy); ctx.stroke(); });
  }
}

// painted interior wall: very soft unevenness and faint scuffs low down
function paintWall(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.69 : 0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);
  paintNoise(ctx, albedo ? 0.015 : 0.06, rand);
  softBlobs(ctx, rand, 8, 60, 160, albedo ? 'rgba(0,0,0,0.035)' : 'rgba(0,0,0,0.04)');
  softBlobs(ctx, rand, 6, 40, 120, albedo ? 'rgba(255,255,255,0.04)' : 'rgba(255,255,255,0.04)');
  fineScratches(ctx, rand, 8, albedo ? 'rgba(0,0,0,0.05)' : 'rgba(60,60,60,0.2)', 40);
}

// cast concrete wall (one tile = 2.4 m): mottled grey, pores, faint damp streaks, the seams of
// the formwork panels and the rows of tie holes they leave behind
function paintConcrete(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.66 : 0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);
  softBlobs(ctx, rand, 26, 30, 140, albedo ? 'rgba(0,0,0,0.07)' : 'rgba(0,0,0,0.05)');
  softBlobs(ctx, rand, 18, 30, 120, albedo ? 'rgba(255,255,255,0.06)' : 'rgba(255,255,255,0.05)');
  // damp streaks running down from the seams
  if (albedo) {
    for (let i = 0; i < 9; i++) {
      const x = rand() * SIZE, w = 6 + rand() * 18, len = 80 + rand() * 260, y = rand() * SIZE;
      wrapped(ctx, (ox, oy) => {
        const g = ctx.createLinearGradient(0, y + oy, 0, y + oy + len);
        g.addColorStop(0, 'rgba(20,24,28,0)');
        g.addColorStop(0.3, 'rgba(20,24,28,0.08)');
        g.addColorStop(1, 'rgba(20,24,28,0)');
        ctx.fillStyle = g;
        ctx.fillRect(x + ox - w / 2, y + oy, w, len);
      });
    }
  }
  paintNoise(ctx, albedo ? 0.07 : 0.25, rand);
  // pores: tiny air bubbles in the surface
  for (let i = 0; i < 1600; i++) {
    const x = rand() * SIZE, y = rand() * SIZE, r = 0.5 + rand() * 1.4;
    ctx.fillStyle = albedo ? 'rgba(30,32,36,0.45)' : gray(0.2, 0.8);
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  }
  // formwork seams: two panels across, one down
  ctx.fillStyle = albedo ? 'rgba(25,28,32,0.35)' : gray(0.32);
  for (const x of [0, SIZE / 2]) { ctx.fillRect(x - 1.5, 0, 3, SIZE); }
  ctx.fillRect(0, -1.5, SIZE, 3);
  ctx.fillRect(0, SIZE - 1.5, SIZE, 3);
  // tie holes: a 4 x 4 grid, every 0.6 m
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      const x = (i + 0.5) * SIZE / 4, y = (j + 0.5) * SIZE / 4;
      ctx.fillStyle = albedo ? 'rgba(255,255,255,0.10)' : gray(0.46);
      ctx.beginPath(); ctx.arc(x, y, 9, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = albedo ? 'rgba(18,20,24,0.85)' : gray(0.08);
      ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
    }
  }
}

// troweled concrete floor (one tile = 3 m): smoother, scuffed, stained, a saw-cut joint and a
// few hairline cracks
function paintConcreteFloor(ctx, mode, seed) {
  const rand = rng(seed), albedo = mode === 'albedo';
  ctx.fillStyle = gray(albedo ? 0.64 : 0.5);
  ctx.fillRect(0, 0, SIZE, SIZE);
  softBlobs(ctx, rand, 20, 40, 170, albedo ? 'rgba(0,0,0,0.08)' : 'rgba(0,0,0,0.03)');
  softBlobs(ctx, rand, 14, 30, 140, albedo ? 'rgba(255,255,255,0.05)' : 'rgba(255,255,255,0.03)');
  softBlobs(ctx, rand, 5, 20, 60, albedo ? 'rgba(10,12,14,0.14)' : 'rgba(0,0,0,0.02)');   // stains
  paintNoise(ctx, albedo ? 0.05 : 0.14, rand);
  for (let i = 0; i < 500; i++) {
    const x = rand() * SIZE, y = rand() * SIZE;
    ctx.fillStyle = albedo ? 'rgba(30,32,36,0.35)' : gray(0.3, 0.7);
    ctx.fillRect(x, y, 1.2, 1.2);
  }
  fineScratches(ctx, rand, 30, albedo ? 'rgba(255,255,255,0.07)' : 'rgba(70,70,70,0.4)', 50);
  // hairline cracks: short wandering lines
  ctx.strokeStyle = albedo ? 'rgba(20,22,26,0.55)' : gray(0.2);
  ctx.lineWidth = 1;
  for (let i = 0; i < 4; i++) {
    let x = rand() * SIZE, y = rand() * SIZE, a = rand() * Math.PI * 2;
    ctx.beginPath(); ctx.moveTo(x, y);
    for (let k = 0; k < 14; k++) { a += (rand() - 0.5) * 1.1; x += Math.cos(a) * 8; y += Math.sin(a) * 8; ctx.lineTo(x, y); }
    ctx.stroke();
  }
  // saw-cut joints along the tile edges
  ctx.fillStyle = albedo ? 'rgba(20,22,26,0.6)' : gray(0.18);
  ctx.fillRect(0, 0, SIZE, 2);
  ctx.fillRect(0, 0, 2, SIZE);
}

function makeTexture(paint, mode, seed, srgb) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = SIZE;
  paint(canvas.getContext('2d'), mode, seed);
  // A slight blur on the height map keeps the bump smooth instead of sparkly: hard one-pixel
  // edges in a height map turn into shimmering noise once they are lit. Drawn tiled so the
  // blur wraps around the edges.
  if (mode === 'height') {
    const soft = document.createElement('canvas');
    soft.width = soft.height = SIZE;
    const sctx = soft.getContext('2d');
    sctx.filter = 'blur(1.6px)';
    for (const ox of [-SIZE, 0, SIZE]) for (const oy of [-SIZE, 0, SIZE]) sctx.drawImage(canvas, ox, oy);
    canvas.getContext('2d').drawImage(soft, 0, 0);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = 8;
  tex.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  tex.needsUpdate = true;
  return tex;
}

// Shared by every hub shader so one update moves all the flowing light
export const hubTime = { value: 0 };

// The colour and height maps packed into one texture (colour in RGB, height in alpha), so the shader
// reads one texture instead of two at every sample: measured as a real saving on integrated graphics.
// Built from the raw pixels as a DataTexture, so the alpha never gets premultiplied into the colour.
function pack(albedoTex, heightTex) {
  const a = albedoTex.image.getContext('2d').getImageData(0, 0, SIZE, SIZE).data;
  const h = heightTex.image.getContext('2d').getImageData(0, 0, SIZE, SIZE).data;
  const data = new Uint8Array(SIZE * SIZE * 4);
  for (let i = 0; i < data.length; i += 4) {
    data[i] = a[i]; data[i + 1] = a[i + 1]; data[i + 2] = a[i + 2]; data[i + 3] = h[i];
  }
  const tex = new THREE.DataTexture(data, SIZE, SIZE, THREE.RGBAFormat);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  tex.anisotropy = 8;
  tex.colorSpace = THREE.SRGBColorSpace;      // (applies to RGB only; the alpha height stays linear)
  tex.flipY = true;                           // match the canvas textures' orientation
  tex.needsUpdate = true;
  return tex;
}

// Real soil for every planter, bed and pot: Poly Haven's Farm Soil (Amal Kumar, CC0, a 2 m
// scan). Packed offline the same way as the drawn textures: colour in RGB, the scan's
// displacement in alpha (contrast stretched, then scaled so the clods' tops sit at 0.52, the
// level parallaxFloor treats as the surface). Loaded only when a model has soil (level 1 has
// none), in the background: the planters show plain soil colour for the moment before it arrives.
function loadSoil() {
  const tex = new THREE.TextureLoader().load('./assets/textures/soil_farm.webp');
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;   // (RGB only; the alpha depth stays linear)
  tex.anisotropy = 8;
  return { albedo: tex, height: tex, packed: tex };
}

// The drawn textures (each kind: albedo, height, and the two packed in one): painting them takes
// about a tenth of a second a kind, so each kind is painted the first time something asks for it,
// and only once for the whole game (Level 1 and Level 2 share them; a level that is torn down only
// frees them on the graphics card, and they go back up when next used).
const PAINTERS = {
  plate: [paintPlate, 11], floor: [paintFloor, 23], paint: [paintPaint, 31], plastic: [paintPlastic, 37],
  fabric: [paintFabric, 41], paper: [paintPaper, 43], label: [paintLabel, 47], brushed: [paintBrushed, 53],
  wall: [paintWall, 59], concrete: [paintConcrete, 61], concreteFloor: [paintConcreteFloor, 67]
};
let shared = null;

export function createHubTextures() {
  shared ??= new Proxy({}, {
    get(sets, kind) {
      if (!(kind in sets) && PAINTERS[kind]) {
        const [paint, seed] = PAINTERS[kind];
        const set = { albedo: makeTexture(paint, 'albedo', seed, true), height: makeTexture(paint, 'height', seed, false) };
        set.packed = pack(set.albedo, set.height);
        sets[kind] = set;
      }
      return sets[kind];
    }
  });
  return shared;
}

// Which texture each model material uses, and how big one tile is in metres
const SURFACES = {
  hull_light: { kind: 'plate', tile: 4.0, bump: 1.6 },
  hull_mid: { kind: 'plate', tile: 3.0, bump: 1.6 },
  hull_dark: { kind: 'plate', tile: 2.5, bump: 1.2 },
  trim: { kind: 'plate', tile: 1.5, bump: 1.2 },
  rust: { kind: 'plate', tile: 3.0, bump: 1.6 },
  pipe_black: { kind: 'plate', tile: 1.2, bump: 0.8 },
  accent: { kind: 'plate', tile: 2.0, bump: 0.6 },
  floor_dark: { kind: 'floor', tile: 4.0, bump: 1.2, depth: 0.04 },   // depth: parallax-mapped grooves (m)
  cont_red: { kind: 'plate', tile: 3.0, bump: 1.4 },
  cont_blue: { kind: 'plate', tile: 3.0, bump: 1.4 },
  cont_mustard: { kind: 'plate', tile: 3.0, bump: 1.4 },
  cont_grey: { kind: 'plate', tile: 3.0, bump: 1.4 },
  // the lab's furniture and objects: realistic surfaces
  navy: { kind: 'paint', tile: 0.7, bump: 0.35 },
  navy_light: { kind: 'paint', tile: 0.7, bump: 0.35 },
  soft_black: { kind: 'paint', tile: 0.6, bump: 0.35 },
  orange: { kind: 'paint', tile: 0.5, bump: 0.3 },
  lab_wall_low: { kind: 'paint', tile: 1.2, bump: 0.3 },
  smooth_white: { kind: 'plastic', tile: 0.45, bump: 0.25 },
  lab_blue: { kind: 'plastic', tile: 0.45, bump: 0.25 },
  whiteboard: { kind: 'plastic', tile: 1.0, bump: 0.1 },
  chair_fabric: { kind: 'fabric', tile: 0.06, bump: 1.0 },
  coat: { kind: 'fabric', tile: 0.05, bump: 0.8 },
  fabric: { kind: 'fabric', tile: 0.07, bump: 1.0 },
  fabric_light: { kind: 'fabric', tile: 0.07, bump: 1.0 },
  cushion_orange: { kind: 'fabric', tile: 0.06, bump: 1.0 },
  cushion_blue: { kind: 'fabric', tile: 0.06, bump: 1.0 },
  paper: { kind: 'paper', tile: 0.3, bump: 0 },
  label: { kind: 'label', tile: 0.16, bump: 0 },
  steel: { kind: 'brushed', tile: 0.3, bump: 0.4 },
  lab_wall: { kind: 'wall', tile: 2.2, bump: 0.25 },
  // the photo carries the soil's colour, so the material colour is lifted to show it as is
  soil: { kind: 'soil', tile: 1.2, bump: 1.6, depth: 0.03, color: 0xd2ccc6 }
};

// How the light flows in each glowing material (GLSL expression giving a multiplier)
const GLOWS = {
  blue_glow: 'vec3 f = vec3(1.0);',
  white_glow: 'vec3 f = vec3(1.0);',
  tile_glow: 'vec3 f = vec3(1.0);',
  lamp_warm: 'vec3 f = vec3(1.0);',
  // electrified water: a slow ripple of light (no flicker)
  water: 'vec3 f = vec3(0.8 + 0.2 * sin(vTriPos.x * 1.3 + uHubTime * 1.4) * sin(vTriPos.z * 1.1 - uHubTime));',
  hazard: 'vec3 f = vec3(1.0);',
  core_energy: 'vec3 f = vec3(0.45 + 0.55 * pow(0.5 + 0.5 * sin(vTriPos.y * 1.1 - uHubTime * 5.0), 2.0));',
  door_a_glow: 'vec3 f = vec3(1.0);',
  door_b_glow: 'vec3 f = vec3(1.0);',
  door_c_glow: 'vec3 f = vec3(1.0);',
  accent_glow: 'vec3 f = vec3(1.0);',
  aria_screen: 'vec3 f = vec3(1.0);'
};

const POS_VARYING = '\nvarying vec3 vTriPos;\nvarying vec3 vTriNrm;\n';

// ------------------------------------------------------------------ uneven, broken lighting
// The atrium should look damaged, not evenly lit. Real lamps would each be worked out for every
// pixel on screen (about 3 ms a frame each on Intel UHD 620), so the unevenness is painted into
// the surfaces' own shader instead:
//   the shade map  a small top-down texture of how much of the room's light reaches each spot,
//                  worked out once when the level loads (bakeShadeMap): dead zones, patches of
//                  soot and dead panels, the darkness under the gallery ring, and an overall dim
//                  so the lamp pools stand out. Red channel: floor level; green: gallery level.
//                  One texture read per pixel instead of that maths (measured: the maths cost
//                  4 to 8 ms a frame in floor-filled views at 1024x768)
//   pools          soft pools of light from the lamps that still work (no shadows): a centre, a
//                  reach and a colour (its brightness). Live uniforms, so the level can flicker
//                  them and turn them red.
// Only inside the atrium's outer wall: the lift cabin, the rooms and the lab are left alone.
export const HUB_POOLS = 8;
const SHADE_SIZE = 128;      // texels across the shade map
const SHADE_SPAN = 35;       // metres the shade map covers (the atrium is 34 m across)
export const hubLighting = {
  uPools: { value: Array.from({ length: HUB_POOLS }, () => new THREE.Vector4(0, -100, 0, 0.001)) },
  uPoolColors: { value: Array.from({ length: HUB_POOLS }, () => new THREE.Color(0, 0, 0)) },
  uShadeMap: { value: null },
  uRestore: { value: 0 }       // 0..1: how far the room's light has come back (the pumps restart)
};

// one plain white map until the level bakes its own: nothing is darkened
{
  const white = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1, THREE.RGBAFormat);
  white.needsUpdate = true;
  hubLighting.uShadeMap.value = white;
}

// The same value noise the shade map was designed with (smooth random blobs)
function hash2(x, y) {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return s - Math.floor(s);
}
function noise2(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y);
  let fx = x - ix, fy = y - iy;
  fx = fx * fx * (3 - 2 * fx);
  fy = fy * fy * (3 - 2 * fy);
  const a = hash2(ix, iy), b = hash2(ix + 1, iy), c = hash2(ix, iy + 1), d = hash2(ix + 1, iy + 1);
  return (a + (b - a) * fx) + ((c + (d - c) * fx) - (a + (b - a) * fx)) * fy;
}
const smooth = (e0, e1, x) => {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
};

// Work out the shade map for a level. zones: [{ at: [x, y, z], reach, depth }] dead areas;
// grime 0..1 how dark the soot patches get; gallery { edge, strength } darkness under the
// gallery ring (from its inner edge outwards, at floor level); dim 0..1 the whole atrium's share
// of the room light. Floor level is sampled at y = 1 m, gallery level at y = 7 m.
export function bakeShadeMap({ zones = [], grime = 0, gallery = { edge: 13.6, strength: 0 }, dim = 1 }) {
  const data = new Uint8Array(SHADE_SIZE * SHADE_SIZE * 4);
  for (let j = 0; j < SHADE_SIZE; j++) {
    for (let i = 0; i < SHADE_SIZE; i++) {
      const x = ((i + 0.5) / SHADE_SIZE - 0.5) * SHADE_SPAN;
      const z = ((j + 0.5) / SHADE_SIZE - 0.5) * SHADE_SPAN;
      const r = Math.hypot(x, z);
      const shadeAt = (y) => {
        const n = noise2(x * 0.22 + y * 0.07, z * 0.22) * 0.6 + noise2(x * 0.6 + y * 0.2 + 7.3, z * 0.6 + 7.3) * 0.4;
        let s = dim * (1 - grime * smooth(0.32, 0.72, n));
        if (y < 5.4) s *= 1 - gallery.strength * smooth(gallery.edge - 0.6, gallery.edge + 0.9, r);
        for (const zone of zones) {
          const d = Math.hypot(x - zone.at[0], y - zone.at[1], z - zone.at[2]);
          s *= 1 - zone.depth * (1 - smooth(0, zone.reach, d));
        }
        return s;
      };
      const k = (j * SHADE_SIZE + i) * 4;
      data[k] = Math.round(255 * Math.min(1, shadeAt(1)));
      data[k + 1] = Math.round(255 * Math.min(1, shadeAt(7)));
      data[k + 2] = 0;
      data[k + 3] = 255;
    }
  }
  const tex = new THREE.DataTexture(data, SHADE_SIZE, SHADE_SIZE, THREE.RGBAFormat);
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearFilter;
  tex.needsUpdate = true;
  hubLighting.uShadeMap.value?.dispose();
  hubLighting.uShadeMap.value = tex;
  return tex;
}

const HUB_LIGHT_GLSL = `
  #define HUB_POOLS ${HUB_POOLS}
  uniform vec4 uPools[HUB_POOLS];
  uniform vec3 uPoolColors[HUB_POOLS];
  uniform sampler2D uShadeMap;
  uniform float uRestore;
  // how much of the room's light reaches this point (1 = all of it), from the baked shade map,
  // brought back towards clean as the power returns
  float hubShade(vec3 p) {
    vec2 shade = texture2D(uShadeMap, p.xz / ${SHADE_SPAN.toFixed(1)} + 0.5).rg;
    float s = mix(shade.r, shade.g, smoothstep(5.0, 5.8, p.y));
    s = mix(s, 1.0, uRestore);
    return mix(1.0, s, 1.0 - smoothstep(16.9, 17.3, length(p.xz)));
  }
  // light from the lamps that still work: soft pools facing their lamp, without shadows
  vec3 hubPools(vec3 p, vec3 n) {
    vec3 c = vec3(0.0);
    for (int i = 0; i < HUB_POOLS; i++) {
      vec3 toLamp = uPools[i].xyz - p;
      float d = length(toLamp);
      float fall = 1.0 - smoothstep(0.0, uPools[i].w, d);
      c += uPoolColors[i] * (fall * fall) * max(dot(n, toLamp / max(d, 0.001)), 0.0);
    }
    return c;
  }
`;

// After the scene's lights are added up: dim them where the room is dark, add the lamp pools
const HUB_LIGHT_APPLY = `#include <aomap_fragment>
  {
    float hubS = hubShade(vTriPos);
    reflectedLight.directDiffuse *= hubS;
    reflectedLight.indirectDiffuse *= hubS;
    reflectedLight.directSpecular *= hubS;
    reflectedLight.indirectSpecular *= hubS;
    reflectedLight.directDiffuse += hubPools(vTriPos, normalize(vTriNrm)) * diffuseColor.rgb;
  }`;

function addHubLighting(shader) {
  Object.assign(shader.uniforms, hubLighting);
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>${HUB_LIGHT_GLSL}`)
    .replace('#include <aomap_fragment>', HUB_LIGHT_APPLY);
}

// The same broken lighting on a material that is not one of the textured surfaces (the plants'
// leaves), so a leaf in a dead corner is as dark as the floor under it
export function withHubLighting(material) {
  material.onBeforeCompile = (shader) => {
    addVertexPosition(shader);
    shader.fragmentShader = shader.fragmentShader.replace('#include <common>', `#include <common>${POS_VARYING}`);
    addHubLighting(shader);
  };
  material.customProgramCacheKey = () => 'hub-lit';
  return material;
}

function addVertexPosition(shader) {
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>${POS_VARYING}`)
    .replace('#include <begin_vertex>',
      '#include <begin_vertex>\n  vTriPos = (modelMatrix * vec4(transformed, 1.0)).xyz;\n  vTriNrm = normalize(mat3(modelMatrix) * objectNormal);');
}

// Turn one of the model's materials into its textured, bump-mapped version
function texturedMaterial(source, spec, textures) {
  const mat = new THREE.MeshStandardMaterial({
    color: spec.color !== undefined ? new THREE.Color(spec.color) : source.color.clone(),
    roughness: source.roughness,
    metalness: source.metalness,
    name: source.name
  });
  if (spec.kind === 'soil' && !textures.soil) textures.soil = loadSoil();
  const tex = textures[spec.kind];
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uAlb = { value: tex.packed };
    shader.uniforms.uTile = { value: spec.tile };
    shader.uniforms.uBump = { value: spec.bump };
    shader.uniforms.uDepth = { value: spec.depth || 0 };
    addVertexPosition(shader);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>${POS_VARYING}
        uniform sampler2D uAlb;            // colour in RGB, height in alpha
        uniform float uTile;
        uniform float uBump;
        uniform float uDepth;
        ${PARALLAX_GLSL}
        vec4 triSample(sampler2D t, vec3 p, vec3 w) {
          vec4 c = vec4(0.0);
          if (w.x > 0.02) c += texture2D(t, p.zy) * w.x;
          if (w.y > 0.02) c += texture2D(t, p.xz) * w.y;
          if (w.z > 0.02) c += texture2D(t, p.xy) * w.z;
          return c;
        }
        // Bends the normal by the slope of the height map (as three.js's own bump mapping does)
        vec3 triPerturb(vec3 surfPos, vec3 surfNorm, vec2 dHdxy, float faceDir) {
          vec3 sx = normalize(dFdx(surfPos));
          vec3 sy = normalize(dFdy(surfPos));
          vec3 r1 = cross(sy, surfNorm);
          vec3 r2 = cross(surfNorm, sx);
          float det = dot(sx, r1) * faceDir;
          vec3 grad = sign(det) * (dHdxy.x * r1 + dHdxy.y * r2);
          return normalize(abs(det) * surfNorm - grad);
        }`)
      .replace('#include <map_fragment>', `#include <map_fragment>
        vec3 triW = pow(abs(normalize(vTriNrm)), vec3(6.0));
        triW = max(triW - 0.02, 0.0);
        triW /= (triW.x + triW.y + triW.z);
        vec3 triP = vTriPos / uTile;
        vec4 triTex;
        if (uDepth > 0.0 && triW.y > 0.9 && vTriNrm.y > 0.0) {
          // a floor: parallax depth in the grooves, which are darker too
          vec3 toEye = cameraPosition - vTriPos;
          float eyeDist = length(toEye);
          triTex = texture2D(uAlb, parallaxFloor(uAlb, triP.xz, toEye / eyeDist, uDepth / uTile, eyeDist));
          diffuseColor.rgb *= 1.0 - 0.5 * pomDepth(triTex);
        } else {
          triTex = triSample(uAlb, triP, triW);
        }
        vec3 triAlb = triTex.rgb;
        float triH = triTex.a;
        diffuseColor.rgb *= triAlb * 1.45;`)
      .replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
        roughnessFactor = clamp(roughnessFactor * (1.55 - triH * 1.1), 0.12, 1.0);`)
      .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
        normal = triPerturb(-vViewPosition, normal, vec2(dFdx(triH), dFdy(triH)) * uBump, faceDirection);`);
    addHubLighting(shader);
  };
  return mat;
}

// A textured material straight from a surface description ({ kind, tile, bump, color, rough,
// metal }, as in levels/level1Look.js), for a model made with another level's surfaces
export function surfaceMaterial(spec, textures, name = '') {
  const source = { color: new THREE.Color(spec.color ?? 0xffffff), roughness: spec.rough ?? 0.5, metalness: spec.metal ?? 0, name };
  return texturedMaterial(source, spec, textures);
}

// Glowing materials keep their colour but their light flows
function glowingMaterial(source, flowGlsl) {
  const mat = source.clone();
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uHubTime = hubTime;
    addVertexPosition(shader);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>${POS_VARYING}\nuniform float uHubTime;`)
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
        {
          ${flowGlsl}
          totalEmissiveRadiance *= f;
        }`);
  };
  return mat;
}

// Swaps the model's plain materials for the textured / flowing versions (in place)
export function applyHubMaterials(root, textures) {
  const cache = new Map();
  const swap = (m) => {
    if (cache.has(m)) return cache.get(m);
    let out = m;
    if (SURFACES[m.name]) out = texturedMaterial(m, SURFACES[m.name], textures);
    else if (GLOWS[m.name]) out = glowingMaterial(m, GLOWS[m.name]);
    cache.set(m, out);
    return out;
  };
  root.traverse((o) => {
    if (!o.isMesh) return;
    o.material = Array.isArray(o.material) ? o.material.map(swap) : swap(o.material);
  });
}
